// counter-dist — shared-memory counter
// Backend: shm

fn cd_create::(name, initial) {
    let shm = @shm_create(name, 16);
    @shm_write(shm, 0, @bytes(@json_encode({"value": initial})));
    return shm;
}

fn cd_open::(name) { return @shm_open_z(name); }

fn cd_get::(shm) {
    return @json_decode(@mem_to_string(@mem_from_bytes(@shm_read(shm, 0, 16))))["value"];
}

fn cd_set::(shm, v) {
    @shm_write(shm, 0, @bytes(@json_encode({"value": v})));
    return v;
}

fn cd_inc::(shm) { let v = cd_get(shm) + 1; cd_set(shm, v); return v; }
fn cd_add::(shm, n) { let v = cd_get(shm) + n; cd_set(shm, v); return v; }
fn cd_reset::(shm) { return cd_set(shm, 0); }

fn version::() { return "1.0.0"; }
